export function auditNativeExits(p,reader,sourceId){const skip=new Set();for(const l of p.links||[])if(l.runtime?.type==='portal')for(const end of ['from',...(l.twoWay?['to']:[])]){const e=l[end];skip.add(e.mapId+':'+e.x+','+e.y);}const out=[];for(const m of p.maps){if(m.rom?.sourceId!==sourceId||m.rom.generated||m.rom.isCopy)continue;const n=reader.byKey(m.rom.key);if(!n)continue;const a=reader.atlas(n),blocks=reader.blocks(n),mask=reader.engine==='frlg'?511:255;for(const e of reader.events(n).warps){const pin=m.markers.find(p=>p.rom?.type==='warp'&&p.rom.index===e.index),x=pin?.x??e.x,y=pin?.y??e.y,i=y*m.width+x,r=m.movement?.[i],behavior=a.attrs[blocks[e.y*n.layout.width+e.x]&1023]&mask,key=m.id+':'+x+','+y;if(skip.has(key)||r?.mode!=='original'||r.behavior!==0||r.collision!==0||!behavior)continue;const state=JSON.stringify({sourceId,behavior,rule:r,x,y}),id=sourceId+':'+key;if(p.nativeExitDecisions?.[id]?.state===state||out.some(c=>c.id===id))continue;out.push({id,state,mapId:m.id,map:m.name,x,y,behavior,mask});}}return out;}
export function resolveNativeExits(existing,conflicts,choices){const p=structuredClone(existing);p.nativeExitDecisions??={};p.nativeExitHistory??=[];for(const c of conflicts){const choice=choices[c.id];if(!['json','native'].includes(choice))throw Error('Choose JSON or source exit behavior for every exit.');const m=p.maps.find(m=>m.id===c.mapId),i=c.y*m.width+c.x,before=structuredClone(m.movement[i]);if(choice==='native'){m.movement[i]={...before,behavior:c.behavior};if(before.nativeAttribute!==undefined)m.movement[i].nativeAttribute=(before.nativeAttribute&~c.mask)|c.behavior;}p.nativeExitHistory.push({...c,choice,before,after:structuredClone(m.movement[i])});p.nativeExitDecisions[c.id]={choice,state:c.state};}delete p.nativeArtworkPacks;return p;}
export function nativeExitReview(api,conflicts,after){const original=api.project(),choices={};api.modal('Review JSON exit behavior',`<p>${conflicts.length} JSON tiles explicitly store zero behavior where the source ROM has an active native exit. JSON remains authoritative unless you choose to restore the source behavior. Other collision, height and layer settings stay intact.</p>${conflicts.map((c,i)=>`<label>${api.esc(c.map)} · ${c.x},${c.y}<select id="exitChoice${i}"><option value="">Choose…</option><option value="json">Keep JSON behavior (exit may be disabled)</option><option value="native">Restore source exit behavior ${c.behavior}</option></select></label>`).join('')}<button type="button" id="exitAllJSON">Keep JSON for all</button><button type="button" id="exitAllNative">Restore source exit behavior for all</button>`,async()=>{if(api.project()!==original)throw Error('The active project changed. Reopen exit review.');for(const[c,i]of conflicts.map((c,i)=>[c,i]))choices[c.id]=api.$('#exitChoice'+i).value;const p=resolveNativeExits(original,conflicts,choices);await api.open(p);after?.();},'Save exit decisions in a copy');api.$('#exitAllJSON').onclick=()=>conflicts.forEach((c,i)=>api.$('#exitChoice'+i).value='json');api.$('#exitAllNative').onclick=()=>conflicts.forEach((c,i)=>api.$('#exitChoice'+i).value='native');}
